import { describe, it, expect } from 'vitest';

// React Testing Library is not installed in this project, so the component
// cannot be rendered in unit tests. These tests pin the toggle logic and
// aria-pressed contract that power ChipBar's behavior.

describe('ChipBar selection toggle logic', () => {
  // mirrors: clicking an unselected chip adds it to the selection
  it('adds an unselected chip id to the selection on toggle', () => {
    const selection = new Set<string>();
    const toggle = (id: string, current: Set<string>): Set<string> => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    };

    const next = toggle('fiction', selection);
    expect(next.has('fiction')).toBe(true);
  });

  it('removes an already-selected chip id from the selection on toggle', () => {
    const selection = new Set(['fiction']);
    const toggle = (id: string, current: Set<string>): Set<string> => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    };

    const next = toggle('fiction', selection);
    expect(next.has('fiction')).toBe(false);
  });

  it('preserves other selections when toggling one chip', () => {
    const selection = new Set(['fiction', 'sci-fi']);
    const toggle = (id: string, current: Set<string>): Set<string> => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    };

    const next = toggle('fiction', selection);
    expect(next.has('sci-fi')).toBe(true);
    expect(next.has('fiction')).toBe(false);
  });

  it('supports multiple chips selected simultaneously', () => {
    const selection = new Set<string>();
    const toggle = (id: string, current: Set<string>): Set<string> => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    };

    const after1 = toggle('fiction', selection);
    const after2 = toggle('sci-fi', after1);
    expect(after2.has('fiction')).toBe(true);
    expect(after2.has('sci-fi')).toBe(true);
  });
});

describe('ChipBar aria-pressed contract', () => {
  // mirrors: aria-pressed={selection.has(id)}
  it('aria-pressed is true for selected chips', () => {
    const selection = new Set(['fiction']);
    const ariaPressedFor = (id: string): boolean => selection.has(id);

    expect(ariaPressedFor('fiction')).toBe(true);
  });

  it('aria-pressed is false for unselected chips', () => {
    const selection = new Set(['fiction']);
    const ariaPressedFor = (id: string): boolean => selection.has(id);

    expect(ariaPressedFor('sci-fi')).toBe(false);
  });

  it('aria-pressed starts as false when no chips are selected', () => {
    const selection = new Set<string>();
    const ariaPressedFor = (id: string): boolean => selection.has(id);

    expect(ariaPressedFor('fiction')).toBe(false);
    expect(ariaPressedFor('sci-fi')).toBe(false);
  });
});

describe('ChipBar onSelectionChange callback contract', () => {
  it('calls onSelectionChange with the new selection after toggling on', () => {
    const calls: Set<string>[] = [];
    const onSelectionChange = (next: Set<string>) => calls.push(next);

    const selection = new Set<string>();
    const next = new Set(selection);
    next.add('fiction');
    onSelectionChange(next);

    expect(calls).toHaveLength(1);
    expect(calls[0].has('fiction')).toBe(true);
  });

  it('calls onSelectionChange with the new selection after toggling off', () => {
    const calls: Set<string>[] = [];
    const onSelectionChange = (next: Set<string>) => calls.push(next);

    const selection = new Set(['fiction']);
    const next = new Set(selection);
    next.delete('fiction');
    onSelectionChange(next);

    expect(calls).toHaveLength(1);
    expect(calls[0].has('fiction')).toBe(false);
  });

  it('does not mutate the previous selection set', () => {
    const selection = new Set(['fiction']);
    const next = new Set(selection);
    next.add('sci-fi');

    // original must be unchanged
    expect(selection.has('sci-fi')).toBe(false);
    expect(next.has('sci-fi')).toBe(true);
  });
