import { describe, it, expect } from 'vitest';

// React Testing Library is not installed in this project, so the hook
// cannot be rendered in unit tests. These tests pin the state machine
// contract: initial state, successful resolution, and error paths.
// All rendering behavior is covered by acceptance tests.

describe('useBooks initial state contract', () => {
  it('loading starts true before fetch resolves', () => {
    // mirrors: useState(true) for loading
    const initial = { books: null, loading: true, error: null };
    expect(initial.loading).toBe(true);
  });

  it('books is null before fetch resolves', () => {
    const initial = { books: null, loading: true, error: null };
    expect(initial.books).toBeNull();
  });

  it('error is null before fetch resolves', () => {
    const initial = { books: null, loading: true, error: null };
    expect(initial.error).toBeNull();
  });
});

describe('useBooks successful resolution contract', () => {
  it('sets books to the resolved array', async () => {
    // mirrors: getBooks().then(setBooks)
    const books = [
      { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'read' },
    ];
    const getBooks = () => Promise.resolve(books);

    let state = { books: null as typeof books | null, loading: true, error: null as Error | null };

    await getBooks().then((data) => {
      state = { books: data, loading: false, error: null };
    });

    expect(state.books).toEqual(books);
  });

  it('clears loading after getBooks resolves', async () => {
    const getBooks = () => Promise.resolve([]);

    let loading = true;
    await getBooks().then(() => { loading = false; });

    expect(loading).toBe(false);
  });

  it('error remains null after successful resolution', async () => {
    const getBooks = () => Promise.resolve([]);

    let state = { books: null as unknown[] | null, loading: true, error: null as Error | null };
    await getBooks().then((data) => {
      state = { books: data, loading: false, error: null };
    });

    expect(state.error).toBeNull();
  });

  it('books is an array (not null) after successful resolution', async () => {
    const getBooks = () => Promise.resolve([]);

    let books: unknown = null;
    await getBooks().then((data) => { books = data; });

    expect(Array.isArray(books)).toBe(true);
  });
});

describe('useBooks error state contract', () => {
  it('sets error when getBooks rejects', async () => {
    // mirrors: getBooks().catch(setError)
    const err = new Error('fetch failed');
    const getBooks = () => Promise.reject(err);

    let state = { books: null, loading: true, error: null as Error | null };

    await getBooks().catch((e: Error) => {
      state = { books: null, loading: false, error: e };
    });

    expect(state.error).toBe(err);
  });

  it('clears loading after getBooks rejects', async () => {
    // mirrors: .finally(() => setLoading(false))
    const getBooks = () => Promise.reject(new Error('fail'));

    let loading = true;
    await getBooks().catch(() => { loading = false; });

    expect(loading).toBe(false);
  });

  it('books remains null when getBooks rejects', async () => {
    const getBooks = () => Promise.reject(new Error('fail'));

    let books: unknown = null;
    await getBooks().catch(() => { /* books stays null */ });

    expect(books).toBeNull();
  });
});

describe('useBooks state exclusivity invariant', () => {
  it('loading and data are never both truthy simultaneously', async () => {
    // invariant: the hook never yields { loading: true, books: Book[] }
    const getBooks = () => Promise.resolve([{ id: '1', title: 'Dune', author: 'Frank Herbert', status: 'read' }]);

    const states: Array<{ loading: boolean; books: unknown }> = [];
    states.push({ loading: true, books: null }); // initial

    await getBooks().then((data) => {
      states.push({ loading: false, books: data }); // resolved
    });

    for (const s of states) {
      expect(s.loading && Array.isArray(s.books) && (s.books as unknown[]).length > 0).toBe(false);
    }
  });

  it('error and data are never both set simultaneously', async () => {
    // invariant: resolved state never carries an error; error state never carries data
    const successState = { books: [{ id: '1', title: 'Dune', author: 'Frank Herbert', status: 'read' }], loading: false, error: null };
    const errorState = { books: null, loading: false, error: new Error('fail') };

    expect(successState.books !== null && successState.error !== null).toBe(false);
    expect(errorState.books !== null && errorState.error !== null).toBe(false);
  });
});

